UPDATE faqs SET question_he = 'מי זכאי להגיש בקשה להלוואה פרטית מדיגילנד?', answer_he = 'כדי להיות זכאים עליכם להיות תושבי ישראל בני 18 ומעלה, בעלי תעודת זהות בתוקף, הכנסה חודשית ברוטו של ₪8,000 לפחות, וציון אשראי של 580 ומעלה. ייתכנו קריטריונים נוספים בהתאם למוצר שנבחר.' WHERE question = 'Who is eligible to apply for a DigiBank personal loan?';
UPDATE faqs SET question_he = 'האם אני יכול/ה להגיש בקשה אם אני עצמאי/ת?', answer_he = 'כן. עצמאים מוזמנים להגיש בקשה. יהיה עליכם לספק שומות מס הכנסה משתי השנים האחרונות ודפי חשבון בנק המראים הפקדות הכנסה סדירות.' WHERE question = 'Can I apply if I am self-employed?';
UPDATE faqs SET question_he = 'מהו סכום ההלוואה המינימלי והמקסימלי?', answer_he = 'טווח ההלוואות הפרטיות שלנו הוא בין ₪5,000 ל-₪300,000, בכפוף לבדיקת יכולת החזר ולמוצר הספציפי שאתם זכאים לו.' WHERE question = 'What is the minimum and maximum loan amount?';
UPDATE faqs SET question_he = 'כמה זמן לוקח למלא את הבקשה?', answer_he = 'מילוי הבקשה המקוונת אורך בדרך כלל 10–15 דקות. לאחר השליחה, מתבצעת בדיקת יכולת החזר אוטומטית מיידית. החלטה מותנית זמינה בדרך כלל תוך דקות.' WHERE question = 'How long does the application take to complete?';
UPDATE faqs SET question_he = 'אילו מסמכים אצטרך?', answer_he = 'תזדקקו ל: תעודת זהות בתוקף, אישור הכנסה (תלושי שכר אחרונים או שומה לעצמאים), דפי חשבון בנק אחרונים (3 חודשים אחרונים), ואישור כתובת (חשבון חברת שירותים או דף בנק).' WHERE question = 'What documents will I need?';
UPDATE faqs SET question_he = 'האם אפשר לשמור את הבקשה ולחזור אליה מאוחר יותר?', answer_he = 'כן. פורטל דיגילנד שומר אוטומטית את ההתקדמות שלכם בכל שלב. פשוט התחברו מחדש והבקשה תמשיך בדיוק מהמקום שבו הפסקתם.' WHERE question = 'Can I save my application and return to it later?';
UPDATE faqs SET question_he = 'מה קורה אחרי שאני שולח/ת את הבקשה?', answer_he = 'הבקשה שלכם עוברת בדיקת יכולת החזר אוטומטית. במקרה של הצלחה, יוצגו לכם מוצרי הלוואה מתאימים. לאחר בחירת מוצר, מונפק אישור מותנה ומסמכי הסכם ההלוואה נוצרים אוטומטית.' WHERE question = 'What happens after I submit my application?';
UPDATE faqs SET question_he = 'אילו ריביות מציעה דיגילנד?', answer_he = 'ריביות ההלוואות הפרטיות שלנו מתחילות מ-4.8% ריבית שנתית ללקוחות זכאים. הריבית המוצעת לכם תלויה בפרופיל האשראי, בסכום ההלוואה, בתקופה ובמוצר שנבחר. הריבית האישית תוצג לפני אישור כל הצעה.' WHERE question = 'What interest rates does DigiBank offer?';
UPDATE faqs SET question_he = 'כיצד מחושב ההחזר החודשי שלי?', answer_he = 'ההחזרים החודשיים מחושבים לפי נוסחת הפחתה סטנדרטית, המחלקת את קרן ההלוואה באופן שווה לאורך התקופה בתוספת ריבית. לוח הסילוקין יימסר לכם במסמכי הסכם ההלוואה.' WHERE question = 'How is my monthly repayment calculated?';
UPDATE faqs SET question_he = 'האם אפשר לבצע פירעון מוקדם?', answer_he = 'כן. דיגילנד מאפשרת פירעון מוקדם חלקי או מלא. ייתכנו עמלות פירעון מוקדם — עיינו בהסכם ההלוואה או פנו ליועץ שלכם לפרטים.' WHERE question = 'Can I make early repayments?';
UPDATE faqs SET question_he = 'באיזה תאריך ייגבו ההחזרים שלי?', answer_he = 'תוכלו לבחור את תאריך ההחזר החודשי המועדף עליכם במהלך הבקשה (בין ה-1 ל-28 בחודש). ההחזרים נגבים בהוראת קבע מחשבון הבנק שציינתם.' WHERE question = 'On which date will my repayments be taken?';
UPDATE faqs SET question_he = 'האם הגשת הבקשה תשפיע על ציון האשראי שלי?', answer_he = 'הבקשה הראשונית מבצעת בדיקת אשראי רכה שאינה משפיעה על ציון האשראי שלכם. בדיקת אשראי מלאה תתבצע רק כאשר תאשרו הצעה מותנית, כפי שמפורט בהצהרת הסכמת האשראי.' WHERE question = 'Will applying affect my credit score?';
UPDATE faqs SET question_he = 'מהו יחס החוב להכנסה (DTI)?', answer_he = 'יחס ה-DTI משווה בין סך ההתחייבויות החודשיות שלכם להכנסה החודשית ברוטו. מדיניות האשראי של דיגילנד דורשת יחס DTI של 40% ומטה. יחס נמוך יותר מעיד על יכולת החזר חזקה יותר.' WHERE question = 'What is the Debt-to-Income (DTI) ratio?';
UPDATE faqs SET question_he = 'בדיקת יכולת ההחזר שלי לא עברה — מה אפשר לעשות?', answer_he = 'אם הבדיקה האוטומטית לא עברה, פנו ליועץ דיגילנד שלכם לבדיקה ידנית. שינויים בנסיבות, מסמכי הכנסה נוספים, או הקטנת סכום ההלוואה עשויים להוביל לתוצאה שונה.' WHERE question = 'My affordability assessment did not pass — what can I do?';
UPDATE faqs SET question_he = 'כיצד דיגילנד מגנה על המידע האישי שלי?', answer_he = 'כל המידע מוצפן בהעברה באמצעות TLS 1.3 ובאחסון באמצעות הצפנת AES-256. דיגילנד פועלת בהתאם לחוק הגנת הפרטיות התשמ"א-1981 ולתקנים מקבילים ל-GDPR.' WHERE question = 'How does DigiBank protect my personal data?';
UPDATE faqs SET question_he = 'מי יכול לראות את פרטי הבקשה שלי?', answer_he = 'רק אנשי צוות מורשים בדיגילנד המעורבים ישירות בטיפול בבקשה שלכם יכולים לגשת למידע שלכם. המידע לעולם לא נמכר ואינו משותף עם צדדים שלישיים לצרכי שיווק.' WHERE question = 'Who can see my application information?';
